transforms.code:
# display the current listable property value rather than displaying 'Select One'

options = value['options']
if options == None:
	return None
else:
	# listable property is set to default value ('value' param is None)
	if value['value'] == None:
		defaultVal = value['default']
		for option in options:
			if defaultVal == option['label']:
				return option['value']
		return None
	else:
		# listable property set to non-default value
		for option in options:
			if str(value['value']) == option['label']:
				return option['value']

		return None

# if property has a binding, text field should be disabled

if 'bindType' in value.keys():
	return False
elif 'enabled' in value.keys():
	if value['enabled'] == 0:
		return False
	else:
		return True
else:
	# if property is 'Name', then check 'enabled' param because
	# name may not be editable if alarm is a UDT alarm
	if value['propName']['value'] == 'Name':
		return value['enabled']
	else:
		return True

# if text field is disabled, return darker grey for background

if 'enabled' in value.keys():
	if value['enabled'] == False:
		return '--neutral-30'
	else:
		return '--neutral-10'
else:
	return '--neutral-10'

# display the current value of the non-listable property

self.props.text = ''
if value['value'] == None:
	return ''
else:
	return value['value']

config.script:
# retrieve info from params and pass this info to updateBindingEditor

rowData = self.view.params.rowData

# grab the underlying name (for example: ackMode vs Ack Mode)
propName = rowData['underlyingName']

# property already has a binding, form 'prop' object
if 'bindType' in rowData.keys():
	bindType = rowData['bindType']
	binding = rowData['value']
	prop = {propName: {'bindType': bindType, 'value': binding}}
else:
	# property does not have a binding
	prop = {}

logger = system.util.getLogger('configurator.tablecell')
logger.debug('the bind icon was pressed; prop name= ' + propName + '; prop= ' + str(prop))

payload = {'name':propName,'prop':prop,'displayName':self.view.params.rowData.propName['value']}	

system.perspective.sendMessage("updateBindingEditor", payload = payload, scope = "page")

